package com.nexus.domain.community;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Component;

/**
 * The community policy, read from the web layer's export instead of restated here (SC-17).
 *
 * <p>{@code contracts/community-policy.json} is generated by {@code npm run contract:export} from
 * {@code packages/schemas/src/community-policy.ts} and copied into this jar by the Maven build. The web
 * domain functions import the same TypeScript module. So there is one place where "which kinds block an
 * interaction" and "which sentence a refusal uses" are written down, and two readers of it.
 *
 * <p>Loading is fail-fast and deliberately strict: a missing key, an empty sentence, or a blocking kind that
 * is not a declared kind stops the context from starting. The alternative — defaulting a missing refusal to
 * {@code ""} or a missing kind list to "nothing blocks" — produces a service that answers 200 while quietly
 * enforcing a different policy from the web layer, which is the exact failure this class exists to prevent.
 *
 * <p>The boundary it carries (same wording as {@code apps/web/src/server/domain/blocks.ts}): {@code mute}
 * hides a person from the viewer's lists and notifications but does NOT stop them liking, following or
 * commenting; {@code block} refuses interactions in both directions. An unrecognised kind is treated as no
 * relation at all, never as a block.
 */
@Component
public class CommunityPolicy {

    static final String RESOURCE = "contracts/community-policy.json";

    private static final List<String> REFUSAL_KEYS =
            List.of("selfFollow", "selfBlock", "unknownKind", "noSuchUser", "noSuchPublication", "publicationGone");

    private final JsonNode root;

    public CommunityPolicy() {
        this(readExport());
    }

    /** Package-private so a test can feed a half-written document and watch the loader refuse it. */
    CommunityPolicy(JsonNode document) {
        List<String> problems = new ArrayList<>();
        List<String> kinds = stringArray(document, "blockKinds", problems);
        List<String> blocking = stringArray(document, "interactionBlockingKinds", problems);
        for (String kind : blocking) {
            if (!kinds.contains(kind)) {
                problems.add("interactionBlockingKinds 里的 " + kind + " 不在 blockKinds 里");
            }
        }
        String me = text(document.path("interactionRefusal"), "me", problems);
        String them = text(document.path("interactionRefusal"), "them", problems);
        if (!me.isEmpty() && me.equals(them)) {
            problems.add("interactionRefusal.me 与 .them 是同一句话：回执就说不清是谁先拉的谁");
        }
        for (String key : REFUSAL_KEYS) {
            text(document.path("refusal"), key, problems);
        }
        JsonNode publication = document.path("publication");
        stringArray(publication, "reachableVisibility", problems);
        text(publication, "rejectedModeration", problems);
        if (!publication.path("deletedProjectHides").isBoolean()) {
            problems.add("publication.deletedProjectHides 必须是布尔");
        }
        if (!problems.isEmpty()) {
            throw new IllegalStateException(RESOURCE + " 不是一份能用的社区策略：" + String.join("；", problems));
        }
        this.root = document;
    }

    private static JsonNode readExport() {
        ClassPathResource resource = new ClassPathResource(RESOURCE);
        if (!resource.exists()) {
            throw new IllegalStateException(
                    "classpath 上没有 " + RESOURCE + "：先在仓库根跑 npm run contract:export，再 mvn package");
        }
        try (InputStream in = resource.getInputStream()) {
            return new ObjectMapper().readTree(in);
        } catch (IOException e) {
            throw new IllegalStateException(RESOURCE + " 读不出来：" + e.getMessage(), e);
        }
    }

    private static List<String> stringArray(JsonNode parent, String field, List<String> problems) {
        JsonNode node = parent.path(field);
        if (!node.isArray() || node.isEmpty()) {
            problems.add(field + " 必须是非空数组");
            return List.of();
        }
        List<String> values = new ArrayList<>();
        for (JsonNode item : node) {
            if (!item.isTextual() || item.asText().isEmpty()) {
                problems.add(field + " 里有非字符串或空串");
                continue;
            }
            values.add(item.asText());
        }
        return List.copyOf(values);
    }

    private static String text(JsonNode parent, String field, List<String> problems) {
        JsonNode node = parent.path(field);
        if (!node.isTextual() || node.asText().isEmpty()) {
            problems.add((parent.isMissingNode() ? "" : ".") + field + " 必须是非空字符串");
            return "";
        }
        return node.asText();
    }

    public List<String> blockKinds() {
        List<String> kinds = new ArrayList<>();
        root.path("blockKinds").forEach(node -> kinds.add(node.asText()));
        return List.copyOf(kinds);
    }

    /** Whether this kind stops an interaction landing on the other person. Unknown kinds do not. */
    public boolean blocksInteraction(String kind) {
        if (kind == null) {
            return false;
        }
        for (JsonNode node : root.path("interactionBlockingKinds")) {
            if (kind.equals(node.asText())) {
                return true;
            }
        }
        return false;
    }

    /** {@code blockedBy} is "me" or "them" — the direction decides which sentence the caller sees. */
    public String interactionRefusal(String blockedBy) {
        return root.path("interactionRefusal").path(blockedBy).asText();
    }

    public String refusal(String key) {
        return root.path("refusal").path(key).asText();
    }

    /**
     * Whether a published version exists for interaction purposes: private, human-rejected and
     * soft-deleted projects do not. {@code unlisted} does — it means "out of discovery, readable by link".
     * Machine moderation ({@code pending} / {@code flagged}) is not part of this predicate.
     */
    public boolean publicationReachable(String visibility, String moderation, boolean projectDeleted) {
        JsonNode publication = root.path("publication");
        if (projectDeleted && publication.path("deletedProjectHides").asBoolean()) {
            return false;
        }
        if (publication.path("rejectedModeration").asText().equals(moderation)) {
            return false;
        }
        for (JsonNode node : publication.path("reachableVisibility")) {
            if (node.asText().equals(visibility)) {
                return true;
            }
        }
        return false;
    }

    /** The document as loaded, for the readout endpoint: which policy this process is actually enforcing. */
    public JsonNode asJson() {
        return root.deepCopy();
    }
}